import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    public static void main(String[] args) throws java.lang.Exception
    {
        // your code goes here
        Scanner in = new Scanner(System.in);
        int t, n, i;
        t = in.nextInt();
        long mod = 998244353;
        int max = 200005;
        long inv[] = new long[max];
        long h[] = new long[max];
        inv[1] = 1;
        for (i = 2; i < max; i++)
            inv[i] = (mod - (mod / i) * inv[(int)mod % i] % mod) % mod;
        h[0] = 0;
        for (i = 1; i < max; i++)
            h[i] = (h[i - 1] + inv[i]) % mod;
        while (t-- != 0)
        {
            n = in.nextInt();
            if (n == 1)
            {
                in.nextLong();
                System.out.println("0");
                continue;
            }
            long arr[] = new long[n];
            for (i = 0; i < n; i++)
                arr[i] = in.nextLong() % mod;
            long ans = 0;
            for (i = 0; i < n; i++)
            {
                long c = (h[i] + h[n - 1 - i]) % mod;
                ans = (ans + arr[i] % mod * c) % mod;
            }
            System.out.println(ans);
        }
    }
}
